from functools import cmp_to_key

def semver_sort(versions):
    def parse(v):
        core = v
        build = None
        if '+' in core:
            core, build = core.split('+', 1)
        pre = None
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = map(int, core.split('.'))
        return (major, minor, patch, pre)

    def compare(v1, v2):
        m1, n1, p1, pre1 = parse(v1)
        m2, n2, p2, pre2 = parse(v2)
        if (m1, n1, p1) != (m2, n2, p2):
            return -1 if (m1, n1, p1) < (m2, n2, p2) else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        ids1 = pre1.split('.')
        ids2 = pre2.split('.')
        for a, b in zip(ids1, ids2):
            if a == b:
                continue
            a_num = a.isdigit()
            b_num = b.isdigit()
            if a_num and b_num:
                ai, bi = int(a), int(b)
                if ai != bi:
                    return -1 if ai < bi else 1
            elif a_num:
                return -1
            elif b_num:
                return 1
            else:
                return -1 if a < b else 1
        if len(ids1) != len(ids2):
            return -1 if len(ids1) < len(ids2) else 1
        return 0

    return sorted(versions, key=cmp_to_key(compare))

